mapper.select:
SELECT COUNT(*)
  FROM tb_role_permission rp
  JOIN tb_role r       ON r.role_seq = rp.role_seq
  JOIN tb_permission p ON p.perm_seq = rp.perm_seq
 WHERE r.role_id = #{roleId}
   AND p.perm_id = #{permId}

SELECT COUNT(*)
  FROM tb_policy p
  JOIN tb_role r ON r.role_seq = p.role_seq
  LEFT JOIN tb_permission pm ON pm.perm_seq = p.perm_seq
 WHERE r.role_id = #{roleId}
   AND p.policy_type = #{policyType}


        AND pm.perm_id = #{permId}


        AND p.perm_seq IS NULL



    AND p.policy_id <> #{exceptPolicyId}
